fn capitalize_words(text: &str) -> String {
    text.split_whitespace()
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn is_palindrome(text: &str) -> bool {
    let chars: Vec<char> = text.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect();
    chars.iter().eq(chars.iter().rev())
}

fn truncate(text: &str, max_chars: usize) -> String {
    if text.chars().count() <= max_chars {
        return text.to_string();
    }
    if max_chars == 0 {
        return String::new();
    }
    let mut out: String = text.chars().take(max_chars - 1).collect();
    out.push('…');
    out
}

fn run_lengths(text: &str) -> String {
    let mut out = String::new();
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        let mut count = 1;
        while chars.peek() == Some(&c) {
            chars.next();
            count += 1;
        }
        out.push(c);
        if count > 1 {
            out.push_str(&count.to_string());
        }
    }
    out
}

fn reverse_words(text: &str) -> String {
    text.split_whitespace().rev().collect::<Vec<_>>().join(" ")
}

unitTests:
test("capitalizing", || {
    check_eq(capitalize_words("élan VITAL"), "Élan Vital");
    check_eq(capitalize_words("  the   quick fox "), "The Quick Fox");
    check_eq(capitalize_words(""), "");
});

test("palindromes", || {
    check(is_palindrome("A man, a plan, a canal: Panama"));
    check(is_palindrome("Été"));
    check(!is_palindrome("hello"));
    check(is_palindrome(""));
});

test("truncating safely", || {
    check_eq(truncate("Grüße aus Köln", 6), "Grüße…");
    check_eq(truncate("short", 10), "short");
    check_eq(truncate("🦀🦀🦀", 2), "🦀…");
    check_eq(truncate("abc", 0), "");
    check_eq(truncate("abc", 3), "abc");
});

test("run lengths", || {
    check_eq(run_lengths("aaabcc"), "a3bc2");
    check_eq(run_lengths("ééé!"), "é3!");
    check_eq(run_lengths(""), "");
});

test("reversing words", || {
    check_eq(reverse_words("one two  three"), "three two one");
    check_eq(reverse_words("solo"), "solo");
});

